import math
from itertools import product

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def check_n(n):
    if n < 2 or n >= 200 or gcd(n, 6) != 1:
        return None

    # Possible range for a: n/3 < a <= n/2
    a_min = math.floor(n / 3) + 1
    a_max = math.floor(n / 2)

    if a_min > a_max:
        # Only one possible a value, or zero. This case is trivial but we handle it anyway.
        # The task specifically asks to investigate cases where |K| >= 2.
        return (n, 1)

    # Check if there are at least two distinct values of k (which corresponds to |A| >= 2)
    # Since a increases by 1, k = n - 2a decreases by 2. The values of k are distinct if a_max > a_min.

    k_values = []
    A_pairs = []
    for a in range(a_min, a_max + 1):
        k = n - 2 * a
        if k >= 1: # k = n - 2a. Since a <= n/2, 2a <= n, so k >= 0. Since a <= n/2 and n is odd (as gcd(n,6)=1), k >= 1.
             A_pairs.append((a, k))
             k_values.append(k)

    # Filter for cases with at least two distinct k values (which means a_max - a_min >= 1)
    if len(k_values) < 2:
        return None

    # Check the condition for every relevant (a, k) pair where k >= 2
    for a, k in A_pairs:
        if k < 2:
            # k=1 always satisfies the condition (C(a-1)/0 = 1/1)
            continue

        # Condition: C(a-1, k-1) must be a multiple of k
        # C(a-1, k-1)
        N_comb = a - 1
        K_comb = k - 1

        try:
            C = combinations(N_comb, K_comb)
            if C % k != 0:
                return (n, 0, f"Failed at a={a}, k={k}. C({N_comb}, {K_comb}) = {C}, not divisible by {k}")
        except ValueError:
             # Should not happen if k >= 2 and a >= 1
             return (n, 0, f"Error calculating combinations for a={a}, k={k}")


    # If all checks pass for this n
    return (n, len(k_values))

# Iterate through all eligible n
solutions = []
for n in range(2, 200):
    result = check_n(n)
    if result:
        solutions.append(result)

print(f"Found {len(solutions)} candidates that satisfy the condition for all pairs (a, k) where |K| >= 2.")
for sol in solutions:
    if len(sol) > 1:
        print(sol)

